# Load trajectory from tar
path='02-main-44tasks.tar.gz'
member='02-main-44tasks/oc-pro__sks-on__meta-off/trials/email-confidential-forward/run-2/trajectory.json'
obj=json.loads(tarfile.open(path,'r:gz').extractfile(member).read())

def content_text(tr):
    obs=tr.get('observation')
    if not obs: return ''
    out=[]
    for res in obs.get('results',[]):
        c=res.get('content','')
        try:
            val=ast.literal_eval(c)
            for item in val:
                out.append(item['content']['text'])
        except Exception as e:
            out.append(c)
    return '\n'.join(out)

for sid in [10,14]:
    txt=content_text(obj['steps'][sid-1])
